 int bg=Color.rgb(5,7,6),panel=Color.rgb(17,22,18),lime=Color.rgb(200,241,105),muted=Color.rgb(157,168,151);StudyDatabase db;LinearLayout root,content;int week=1;long activeCbt=-1;int questionIndex=0;java.util.List<StudyDatabase.Question> currentQuestions=new java.util.ArrayList<>();Handler clock=new Handler();Runnable clockTick;CountDownTimer focusTimer;long focusStarted=0;String[] days={"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};
